import math

def count_zeros(n):
    """Counts the number of zeros in the decimal representation of a positive integer n."""
    if n <= 0:
        return 0
    s = str(n)
    return s.count('0')

# Generate all 3-digit numbers M composed only of non-zero digits
M_candidates = []
for m in range(100, 1000):
    s_m = str(m)
    if '0' not in s_m:
        M_candidates.append(m)

max_A = 0
best_cases = []

print("--- Computational Exploration Results ---")

for M in M_candidates:
    # We test N such that Q = floor(M/N) has at least 3 digits for a meaningful check,
    # although for M=999, Q only goes up to 3 digits anyway.
    # Let's test N up to M/2 to ensure Q has at least 2 digits, and slightly more for robustness.
    N_limit = M // 2 

    for N in range(1, N_limit + 1):
        Q = M // N
        A = count_zeros(Q)

        if A > max_A:
            max_A = A
            best_cases = [(M, N, A)]
        elif A == max_A and A > 0:
            best_cases.append((M, N, A))

        # We stop if A gets too large, though for 3-digit M this is unlikely.
        if A >= 3:
            print(f"Found A={A} for M={M}, N={N}. Stopping search for M={M}.")
            break

# Display results
if max_A > 0:
    print(f"\nMaximum A found for 3-digit M is: {max_A}")
    print("Cases achieving this maximum A:")
    for M, N, A in best_cases:
        print(f"  M={M}, N={N}, Q={M//N}, A={A}")
else:
    print("\nNo zeros found (A=0) for the explored range.")

